#include <algorithm>
#include <map>
#include <optional>
#include <string>
#include <vector>

struct ThreadInfo
{
    int id;
    std::vector<std::string> holds;
    std::optional<std::string> waitingFor;
};

std::vector<int> findDeadlock(const std::vector<ThreadInfo>& threads)
{
    std::map<std::string, int> owner;                 // lock -> thread holding it
    for (const ThreadInfo& t : threads)
        for (const std::string& lock : t.holds) owner[lock] = t.id;

    std::map<int, int> waitsFor;                      // thread -> thread it waits for (at most one)
    for (const ThreadInfo& t : threads)
        if (t.waitingFor)
            if (auto it{ owner.find(*t.waitingFor) }; it != owner.end() && it->second != t.id) waitsFor[t.id] = it->second;

    std::vector<int> best;
    for (const auto& [start, ignored] : waitsFor)
    {
        // Follow the chain from start; each thread has at most one outgoing edge.
        std::vector<int> path;
        int at{ start };
        while (waitsFor.count(at) && std::find(path.begin(), path.end(), at) == path.end())
        {
            path.push_back(at);
            at = waitsFor[at];
        }
        const auto loopStart{ std::find(path.begin(), path.end(), at) };
        if (loopStart == path.end()) continue;        // the chain ended: no cycle from here
        std::vector<int> cycle(loopStart, path.end());
        std::rotate(cycle.begin(), std::min_element(cycle.begin(), cycle.end()), cycle.end());
        if (best.empty() || cycle.front() < best.front()) best = cycle;
    }
    return best;
}

unitTests:
using Ids = std::vector<int>;
TEST("the example") { CHECK(findDeadlock({ { 1, { "A" }, "B" }, { 2, { "B" }, "A" }, { 3, {}, "A" } }) == Ids({ 1, 2 })); }
TEST("no deadlock") { CHECK(findDeadlock({ { 1, { "A" }, "B" }, { 2, { "B" }, std::nullopt } }).empty()); }
TEST("three threads in a ring") { CHECK(findDeadlock({ { 7, { "X" }, "Y" }, { 4, { "Y" }, "Z" }, { 9, { "Z" }, "X" } }) == Ids({ 4, 9, 7 })); }
TEST("waiting for a free lock is not a deadlock") { CHECK(findDeadlock({ { 1, {}, "Q" } }).empty()); }
TEST("two separate cycles: the one with the smallest id") { CHECK(findDeadlock({ { 5, { "A" }, "B" }, { 6, { "B" }, "A" }, { 2, { "C" }, "D" }, { 3, { "D" }, "C" } }) == Ids({ 2, 3 })); }
TEST("nothing at all") { CHECK(findDeadlock({}).empty()); }

